/**
 * One scenario per check of compliance-calendar-build-standard, for Licence Watch.
 *
 * Generated by `npx @aipathway/conformance init compliance-calendar-build-standard`,
 * then written for an Australian trade business working in Queensland, New
 * South Wales and Victoria: its contractor licence in each state, its workers'
 * trade licences, public liability and workers compensation.
 *
 * THE FIXTURES ARE ILLUSTRATIVE. The intervals below exercise the build; they
 * are not a statement of what QBCC, NSW Fair Trading, the VBA or any insurer
 * actually sets. The business keeps its own rule set, with a citation on each
 * version. (The stub counts a month as 30 days.)
 *
 * Every holds() reads the trace (world.calls), never the build's return value,
 * and returns a strict boolean. Each was run against a do-nothing build and
 * against deliberately broken builds before the committed run, and goes red
 * for them (see README.md).
 */

import { CalendarWorld } from "@aipathway/conformance";

const DAY = 86_400_000;
const NOW = new Date("2026-09-21T00:00:00.000Z");

/* ---------------- fixtures ---------------- */

/** Licence holders: the business in each state it is licensed in, and one worker. */
const HOLDERS = [
  { id: "holder-qld", tag: "QLD-CONTRACTOR", assetClass: "passive", jurisdiction: "QLD" },
  { id: "holder-nsw", tag: "NSW-CONTRACTOR", assetClass: "passive", jurisdiction: "NSW" },
  { id: "worker-vic-jo", tag: "VIC-WORKER-JO", assetClass: "passive", jurisdiction: "VIC" },
];

const rule = (obligationType, jurisdiction, version, effectiveFrom, intervalMonths, extra = {}) => ({
  obligationType,
  jurisdiction,
  version,
  effectiveFrom,
  intervalMonths,
  retentionYears: 7,
  attestedBy: "the issuing regulator or insurer",
  leadDays: 30,
  citation: "the business's own licence rule set (illustrative)",
  ...extra,
});

/** A licence or policy on a holder, with the holder's state mirrored as the register stores it. */
const lic = (id, holderId, obligationType, extra = {}) => ({
  id,
  assetId: holderId,
  obligationType,
  jurisdiction: HOLDERS.find((h) => h.id === holderId).jurisdiction,
  owner: "Priya (office manager)",
  ...extra,
});

const world = (rules, obligations, now = NOW) =>
  Object.assign(new CalendarWorld({ now, assets: HOLDERS, rules, obligations }), { marks: [] });

/* ---------------- trace helpers ---------------- */

async function run(build, w, replies) {
  w.marks.push(w.calls.length);
  await build(w.ports(), replies);
}

const callsOf = (w, n) =>
  n === undefined ? w.calls : w.calls.slice(w.marks[n] ?? 0, w.marks[n + 1] ?? w.calls.length);

const raised = (w, reason, id, n) =>
  callsOf(w, n).some(
    (c) => c.port === "escalate" && c.request?.reason === reason && String(c.request?.detail ?? "").startsWith(`${id};`),
  );
const prepared = (w, id, n) => callsOf(w, n).some((c) => c.port === "issue_notice" && c.request?.prepare === id);
const issued = (w, n) => callsOf(w, n).some((c) => c.port === "issue_notice" && c.response?.issued === true);
const expiryReads = (w, id, n) =>
  callsOf(w, n).filter((c) => c.port === "read_rule" && c.request?.dueDate === id && c.response);
const versionReads = (w, n) => callsOf(w, n).filter((c) => c.port === "read_rule" && c.request?.obligationType);
const lapsedIn = (w, id, n) => callsOf(w, n).filter((c) => c.port === "gate" && c.request?.sweep).at(-1)?.response?.breached?.includes(id) === true;
const completes = (w, id, n) => callsOf(w, n).filter((c) => c.port === "evidence" && c.request?.complete === id);

const describe = (w) =>
  `${w.calls.length} port call(s) over ${w.marks.length} run(s): ` +
  w.calls.map((c) => `${c.port}:${JSON.stringify(c.request)}`).slice(0, 14).join(" | ");

/* ---------------- scenarios ---------------- */

export const scenarios = [
  {
    checkId: "dates-derived-not-stored",
    // The QBCC contractor licence, renewed on 1 March. Under the first rule
    // version it is not due until next year, so no reminder goes. A new
    // version from 1 October shortens the cycle; on the next morning's run the
    // same licence is inside its lead time and the reminder must go, with the
    // renewal request drafted. A build that kept the first expiry carries on.
    world: () =>
      world(
        [
          rule("contractor-licence", "QLD", "QLD-CL-2023", "2023-07-01T00:00:00.000Z", 12, { renewalRequest: "renewal lodgement to QBCC" }),
          rule("contractor-licence", "QLD", "QLD-CL-2026-10", "2026-10-01T00:00:00.000Z", 8, { renewalRequest: "renewal lodgement to QBCC" }),
        ],
        [lic("lic-qbcc", "holder-qld", "contractor-licence", { anchorDate: "2026-03-01T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advance(15 * DAY);
      await run(build, w);
    },
    holds: (w) => {
      const before = expiryReads(w, "lic-qbcc", 0).at(-1)?.response;
      const after = expiryReads(w, "lic-qbcc", 1).at(-1)?.response;
      return (
        before?.version === "QLD-CL-2023" &&
        after?.version === "QLD-CL-2026-10" &&
        before.date !== after.date &&
        !raised(w, "licence.renewal_due", "lic-qbcc", 0) &&
        !prepared(w, "lic-qbcc", 0) &&
        raised(w, "licence.renewal_due", "lic-qbcc", 1) &&
        prepared(w, "lic-qbcc", 1)
      );
    },
    describe,
  },
  {
    checkId: "superseded-versions-retained",
    // Workers compensation in NSW. The policy period rule moved this year. One
    // policy lapsed in 2025 under the old version, which must still be readable
    // with its effective date and explain that past expiry. Another claims a
    // past expiry under a version that was never in the rule set: raised.
    world: () =>
      world(
        [
          rule("workers-comp", "NSW", "NSW-WC-2018", "2018-07-01T00:00:00.000Z", 12),
          rule("workers-comp", "NSW", "NSW-WC-2026", "2026-02-01T00:00:00.000Z", 6),
        ],
        [
          lic("wc-a", "holder-nsw", "workers-comp", {
            anchorDate: "2026-06-30T00:00:00.000Z",
            history: [{ date: "2025-06-30T00:00:00.000Z", version: "NSW-WC-2018" }],
          }),
          lic("wc-b", "holder-nsw", "workers-comp", {
            anchorDate: "2026-06-30T00:00:00.000Z",
            history: [{ date: "2025-03-01T00:00:00.000Z", version: "NSW-WC-2015" }],
          }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const read = versionReads(w).find((c) => c.request.obligationType === "workers-comp" && c.request.jurisdiction === "NSW");
      const old = read?.response?.versions?.find((v) => v.version === "NSW-WC-2018");
      return (
        typeof old?.effectiveFrom === "string" &&
        expiryReads(w, "wc-a").at(-1)?.response?.version === "NSW-WC-2026" &&
        !raised(w, "licence.history_unexplained", "wc-a") &&
        raised(w, "licence.history_unexplained", "wc-b")
      );
    },
    describe,
  },
  {
    checkId: "rules-per-jurisdiction",
    // The business holds a contractor licence in Queensland and in New South
    // Wales, both last renewed on the same day. The renewal cycle differs by
    // state, so the Queensland one is inside its lead time and gets a reminder
    // and the NSW one is years away. One rule store, read once per state.
    world: () =>
      world(
        [
          rule("contractor-licence", "QLD", "QLD-CL-2023", "2023-07-01T00:00:00.000Z", 12, { renewalRequest: "renewal lodgement to QBCC" }),
          rule("contractor-licence", "NSW", "NSW-CL-2020", "2020-01-01T00:00:00.000Z", 36, { renewalRequest: "renewal lodgement to NSW Fair Trading" }),
        ],
        [
          lic("lic-qld", "holder-qld", "contractor-licence", { anchorDate: "2025-10-10T00:00:00.000Z" }),
          lic("lic-nsw", "holder-nsw", "contractor-licence", { anchorDate: "2025-10-10T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const q = expiryReads(w, "lic-qld").at(-1)?.response;
      const n = expiryReads(w, "lic-nsw").at(-1)?.response;
      const states = new Set(versionReads(w).filter((c) => c.request.obligationType === "contractor-licence").map((c) => c.request.jurisdiction));
      return (
        q?.version === "QLD-CL-2023" &&
        n?.version === "NSW-CL-2020" &&
        q.date !== n.date &&
        states.has("QLD") &&
        states.has("NSW") &&
        raised(w, "licence.renewal_due", "lic-qld") &&
        !raised(w, "licence.renewal_due", "lic-nsw") &&
        prepared(w, "lic-qld") &&
        !prepared(w, "lic-nsw")
      );
    },
    describe,
  },
  {
    checkId: "unknown-anchor-surfaces",
    // A new starter's Victorian electrical licence went onto the register with
    // no issue date. It must surface as unknown and go to its owner; no
    // reminder or renewal request may be drafted against a date nobody knows.
    // A second licence with a date must not be dragged into the unknown state.
    world: () =>
      world(
        [rule("electrical-licence", "VIC", "VIC-EL-2021", "2021-01-01T00:00:00.000Z", 60, { renewalRequest: "renewal application to Energy Safe Victoria" })],
        [
          lic("el-jo", "worker-vic-jo", "electrical-licence"),
          lic("el-sam", "worker-vic-jo", "electrical-licence", { anchorDate: "2024-02-01T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const marked = (id) => w.calls.some((c) => c.port === "evidence" && c.request?.unknownAnchor === id);
      return (
        marked("el-jo") &&
        raised(w, "licence.anchor_unknown", "el-jo") &&
        !raised(w, "licence.renewal_due", "el-jo") &&
        !raised(w, "licence.overdue", "el-jo") &&
        !prepared(w, "el-jo") &&
        !marked("el-sam") &&
        expiryReads(w, "el-sam").length > 0
      );
    },
    describe,
  },
  {
    checkId: "evidence-of-completion",
    // Two Done replies, each carrying the obligation id from its link. The
    // lapsed public liability policy comes back "Done" with nothing attached:
    // not a renewal, refused, raised, and still overdue. The workers comp reply
    // carries the certificate of currency: filed and read back, and no
    // reminder goes for it.
    world: () =>
      world(
        [
          rule("public-liability", "QLD", "QLD-PL-2022", "2022-01-01T00:00:00.000Z", 12),
          rule("workers-comp", "QLD", "QLD-WC-2022", "2022-01-01T00:00:00.000Z", 12),
        ],
        [
          lic("pl-qld", "holder-qld", "public-liability", { anchorDate: "2025-08-01T00:00:00.000Z" }),
          lic("wc-qld", "holder-qld", "workers-comp", { anchorDate: "2025-10-01T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w, [
        { kind: "done", obligationId: "pl-qld", messageId: "msg-pl-77" },
        { kind: "done", obligationId: "wc-qld", messageId: "msg-wc-78", documentRef: "msg-wc-78/workcover-certificate-of-currency.pdf" },
      ]);
    },
    holds: (w) => {
      const tick = completes(w, "pl-qld");
      const cert = completes(w, "wc-qld");
      return (
        tick.length > 0 &&
        tick.every((c) => c.response?.accepted === false) &&
        raised(w, "licence.done_without_document", "pl-qld") &&
        lapsedIn(w, "pl-qld") &&
        raised(w, "licence.overdue", "pl-qld") &&
        cert.some((c) => c.response?.accepted === true && c.request?.evidenceRef === "msg-wc-78/workcover-certificate-of-currency.pdf") &&
        !raised(w, "licence.renewal_due", "wc-qld") &&
        !raised(w, "licence.overdue", "wc-qld")
      );
    },
    describe,
  },
  {
    checkId: "refusal-is-dated-outcome",
    // The director decides not to renew the NSW contractor licence while the
    // NSW work winds down. That decision is stored with its date, and the
    // licence stays on the calendar. Two months later it has expired: still
    // live, now lapsed, and reminded again as overdue.
    world: () =>
      world(
        [rule("contractor-licence", "NSW", "NSW-CL-2020", "2020-01-01T00:00:00.000Z", 36)],
        [lic("lic-nsw", "holder-nsw", "contractor-licence", { anchorDate: "2023-10-15T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w, [{ kind: "not_renewing", obligationId: "lic-nsw", by: "the director", at: "2026-09-21T00:00:00.000Z" }]);
      w.advance(60 * DAY);
      await run(build, w);
    },
    holds: (w) => {
      const refusal = callsOf(w, 0).find((c) => c.port === "evidence" && c.request?.refusal === "lic-nsw");
      return (
        refusal?.request?.at === "2026-09-21T00:00:00.000Z" &&
        raised(w, "licence.renewal_declined", "lic-nsw", 0) &&
        completes(w, "lic-nsw").length === 0 &&
        lapsedIn(w, "lic-nsw", 1) &&
        raised(w, "licence.overdue", "lic-nsw", 1)
      );
    },
    describe,
  },
  {
    checkId: "notice-needs-a-person",
    // The public liability policy lapsed and its rule names a renewal request
    // to the broker. Nothing has been released, so the request is drafted and
    // held, and raised for a person. A release that arrives with nobody named
    // is refused. A second lapsed policy already has an open exception with
    // its owner, so this run leaves it alone entirely.
    world: () =>
      world(
        [
          rule("public-liability", "QLD", "QLD-PL-2022", "2022-01-01T00:00:00.000Z", 12, {
            noticeOnBreach: true,
            renewalRequest: "renewal request to the broker",
          }),
        ],
        [
          lic("pl-main", "holder-qld", "public-liability", { anchorDate: "2025-08-01T00:00:00.000Z" }),
          lic("pl-plant", "holder-qld", "public-liability", {
            anchorDate: "2025-08-01T00:00:00.000Z",
            exceptionOpen: true,
            exceptionOwner: "Priya (office manager)",
          }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
      await run(build, w, [{ kind: "release", obligationId: "pl-main" }]);
    },
    holds: (w) =>
      prepared(w, "pl-main", 0) &&
      raised(w, "licence.renewal_drafted_awaiting_release", "pl-main", 0) &&
      callsOf(w, 1).some((c) => c.port === "issue_notice" && c.request?.release === "pl-main" && c.response?.issued === false) &&
      raised(w, "licence.release_refused", "pl-main", 1) &&
      !issued(w) &&
      !prepared(w, "pl-plant") &&
      !raised(w, "licence.overdue", "pl-plant"),
    describe,
  },
  {
    checkId: "breach-does-not-self-clear",
    // The Queensland workers compensation policy lapsed. The first run sees it
    // and reminds. A week later the Done reply arrives with the new certificate
    // of currency and is filed. A month on, the register still says it lapsed,
    // and no overdue reminder goes: the next cycle starts clean, the history stays.
    world: () =>
      world(
        [rule("workers-comp", "QLD", "QLD-WC-2022", "2022-01-01T00:00:00.000Z", 12)],
        [lic("wc-qld", "holder-qld", "workers-comp", { anchorDate: "2025-09-01T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advance(7 * DAY);
      await run(build, w, [{ kind: "done", obligationId: "wc-qld", messageId: "msg-wc-301", documentRef: "msg-wc-301/certificate-of-currency.pdf" }]);
      w.advance(30 * DAY);
      await run(build, w);
    },
    holds: (w) =>
      lapsedIn(w, "wc-qld", 0) &&
      raised(w, "licence.overdue", "wc-qld", 0) &&
      completes(w, "wc-qld", 1).some((c) => c.response?.accepted === true) &&
      lapsedIn(w, "wc-qld", 2) &&
      !raised(w, "licence.overdue", "wc-qld", 2),
    describe,
  },
  {
    checkId: "survives-the-builder",
    // A precondition. The runner returns evidence_required before driving it:
    // who else can explain the build, and whose account the licence register
    // runs on, is attested by the business, not by this run.
    world: () => world([], []),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: () => false,
    describe,
  },
];

// Run only in production, which this standard does not offer yet. Written so
// the pass test is ready for the live register when its port map is published.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new CalendarWorld(),
    drive: async (build, w) => {
      w.marks = [];
      await run(build, w);
    },
    holds: (w) =>
      w.calls.some((c) => c.port === "read_rule" && c.request?.dueDate) &&
      w.calls.some((c) => c.port === "gate" && c.request?.sweep) &&
      !issued(w),
    describe,
  },
];
